    85  /** all relevant information about parsing file information */
    86  struct ParseFileInfo
    87  {
    88      // file related info
    89      mode_t perm;            // permissions of this file
    90      // TODO: use quint32 instead of a uint?
    91      uint atime;         // last access time (UNIX format)
    92      uint mtime;         // modification time (UNIX format)
    93      uint ctime;         // creation time (UNIX format)
    94      int uid;            // user id (-1 if not specified)
    95      int gid;            // group id (-1 if not specified)
    96      QByteArray guessed_symlink; // guessed symlink target
    97      int extralen;           // length of extra field
    98
    99      // parsing related info
   100      bool exttimestamp_seen; // true if extended timestamp extra field
   101      // has been parsed
   102      bool newinfounix_seen;  // true if Info-ZIP Unix New extra field has
   103      // been parsed
   104
   105      ParseFileInfo()
   106          : perm(0100644)
   107          , uid(-1)
   108          , gid(-1)
   109          , extralen(0)
   110          , exttimestamp_seen(false)
   111          , newinfounix_seen(false)
   112      {
   113          ctime = mtime = atime = time(nullptr);
   114      }
   115  };
