   392  class Q_DECL_HIDDEN KZip::KZipPrivate
   393  {
   394  public:
   395      KZipPrivate()
   396          : m_crc(0)
   397          , m_currentFile(nullptr)
   398          , m_currentDev(nullptr)
   399          , m_compression(8)
   400          , m_extraField(KZip::NoExtraField)
   401          , m_offset(0)
   402      {
   403      }
   404
   405      unsigned long           m_crc;         // checksum
   406      KZipFileEntry          *m_currentFile; // file currently being written
   407      QIODevice              *m_currentDev;  // filterdev used to write to the above file
   408      QList<KZipFileEntry *> m_fileList;   // flat list of all files, for the index (saves a recursive method ;)
   409      int                     m_compression;
   410      KZip::ExtraField        m_extraField;
   411      // m_offset holds the offset of the place in the zip,
   412      // where new data can be appended. after openarchive it points to 0, when in
   413      // writeonly mode, or it points to the beginning of the central directory.
   414      // each call to writefile updates this value.
   415      quint64                 m_offset;
   416  };
