   439  bool KZip::openArchive(QIODevice::OpenMode mode)
   440  {
   441      //qCDebug(KArchiveLog);
   442      d->m_fileList.clear();
   443
   444      if (mode == QIODevice::WriteOnly) {
   445          return true;
   446      }
   447
   448      char buffer[47];
   449
   450      // Check that it's a valid ZIP file
   451      // KArchive::open() opened the underlying device already.
   452
   453      quint64 offset = 0; // holds offset, where we read
   454      // contains information gathered from the local file headers
   455      QHash<QByteArray, ParseFileInfo> pfi_map;
   456
   457      QIODevice *dev = device();
   458
   459      // We set a bool for knowing if we are allowed to skip the start of the file
   460      bool startOfFile = true;
   461
   462      for (;;) { // repeat until 'end of entries' signature is reached
   463          //qCDebug(KArchiveLog) << "loop starts";
   464          //qCDebug(KArchiveLog) << "dev->pos() now : " << dev->pos();
   465          int n = dev->read(buffer, 4);
   466
   467          if (n < 4) {
   468              setErrorString(tr("Invalid ZIP file. Unexpected end of file. (Error code: %1)").arg(1));
   469              return false;
   470          }
   471
   472          if (!memcmp(buffer, "PK\5\6", 4)) { // 'end of entries'
   473              //qCDebug(KArchiveLog) << "PK56 found end of archive";
   474              startOfFile = false;
   475              break;
   476          }
   477
   478          if (!memcmp(buffer, "PK\3\4", 4)) { // local file header
   479              //qCDebug(KArchiveLog) << "PK34 found local file header";
   480              startOfFile = false;
   481              // can this fail ???
   482              dev->seek(dev->pos() + 2); // skip 'version needed to extract'
   483
   484              // read static header stuff
   485              n = dev->read(buffer, 24);
   486              if (n < 24) {
   487                  setErrorString(tr("Invalid ZIP file. Unexpected end of file. (Error code: %1)").arg(4));
   488                  return false;
   489              }
   490
   491              int gpf = (uchar)buffer[0]; // "general purpose flag" not "general protection fault" ;-)
   492              int compression_mode = (uchar)buffer[2] | (uchar)buffer[3] << 8;
   493              uint mtime = transformFromMsDos(buffer + 4);
   494
   495              const qint64 compr_size = uint(uchar(buffer[12])) | uint(uchar(buffer[13])) << 8 |
   496                                        uint(uchar(buffer[14])) << 16 | uint(uchar(buffer[15])) << 24;
   497              const qint64 uncomp_size = uint(uchar(buffer[16])) | uint(uchar(buffer[17])) << 8 |
   498                                         uint(uchar(buffer[18])) << 16 | uint(uchar(buffer[19])) << 24;
   499              const int namelen = uint(uchar(buffer[20])) | uint(uchar(buffer[21])) << 8;
   500              const int extralen = uint(uchar(buffer[22])) | uint(uchar(buffer[23])) << 8;
   501
   502              /*
   503                qCDebug(KArchiveLog) << "general purpose bit flag: " << gpf;
   504                qCDebug(KArchiveLog) << "compressed size: " << compr_size;
   505                qCDebug(KArchiveLog) << "uncompressed size: " << uncomp_size;
   506                qCDebug(KArchiveLog) << "namelen: " << namelen;
   507                qCDebug(KArchiveLog) << "extralen: " << extralen;
   508                qCDebug(KArchiveLog) << "archive size: " << dev->size();
   509              */
   510
   511              // read fileName
   512              Q_ASSERT(namelen > 0);
   513              QByteArray fileName = dev->read(namelen);
   514              if (fileName.size() < namelen) {
   515                  setErrorString(tr("Invalid ZIP file. Name not completely read (#2)"));
   516                  return false;
   517              }
   518
   519              ParseFileInfo pfi;
   520              pfi.mtime = mtime;
   521
   522              // read and parse the beginning of the extra field,
   523              // skip rest of extra field in case it is too long
   524              unsigned int extraFieldEnd = dev->pos() + extralen;
   525              pfi.extralen = extralen;
   526              int handledextralen = qMin(extralen, (int)sizeof buffer);
   527
   528              //if (handledextralen)
   529              //    qCDebug(KArchiveLog) << "handledextralen: " << handledextralen;
   530
   531              n = dev->read(buffer, handledextralen);
   532              // no error msg necessary as we deliberately truncate the extra field
   533              if (!parseExtraField(buffer, handledextralen, true, pfi)) {
   534                  setErrorString(tr("Invalid ZIP File. Broken ExtraField."));
   535                  return false;
   536              }
   537
   538              // jump to end of extra field
   539              dev->seek(extraFieldEnd);
   540
   541              // we have to take care of the 'general purpose bit flag'.
   542              // if bit 3 is set, the header doesn't contain the length of
   543              // the file and we look for the signature 'PK\7\8'.
   544              if (gpf & 8) {
   545                  // here we have to read through the compressed data to find
   546                  // the next PKxx
   547                  if (!seekToNextHeaderToken(dev, true)) {
   548                      setErrorString(tr("Could not seek to next header token"));
   549                      return false;
   550                  }
   551              } else {
   552                  // here we skip the compressed data and jump to the next header
   553                  //qCDebug(KArchiveLog) << "general purpose bit flag indicates, that local file header contains valid size";
   554                  bool foundSignature = false;
   555                  // check if this could be a symbolic link
   556                  if (compression_mode == NoCompression
   557                      && uncomp_size <= max_path_len
   558                      && uncomp_size > 0) {
   559                      // read content and store it
   560                      // If it's not a symlink, then we'll just discard the data for now.
   561                      pfi.guessed_symlink = dev->read(uncomp_size);
   562                      if (pfi.guessed_symlink.size() < uncomp_size) {
   563                          setErrorString(tr("Invalid ZIP file. Unexpected end of file. (#5)"));
   564                          return false;
   565                      }
   566                  } else {
   567                      if (compr_size > dev->size()) {
   568                          // here we cannot trust the compressed size, so scan through the compressed
   569                          // data to find the next header
   570                          if (!seekToNextHeaderToken(dev, false)) {
   571                              setErrorString(tr("Could not seek to next header token"));
   572                              return false;
   573                          }
   574                          foundSignature = true;
   575                      } else {
   576  //          qCDebug(KArchiveLog) << "before interesting dev->pos(): " << dev->pos();
   577                          bool success = dev->seek(dev->pos() + compr_size); // can this fail ???
   578                          Q_UNUSED(success); // prevent warning in release builds.
   579                          Q_ASSERT(success); // let's see...
   580                          /*          qCDebug(KArchiveLog) << "after interesting dev->pos(): " << dev->pos();
   581                                                  if (success)
   582                                                  qCDebug(KArchiveLog) << "dev->at was successful... ";
   583                                                  else
   584                                                  qCDebug(KArchiveLog) << "dev->at failed... ";*/
   585                      }
   586
   587                  }
   588                  // test for optional data descriptor
   589                  if (!foundSignature) {
   590  //                     qCDebug(KArchiveLog) << "Testing for optional data descriptor";
   591                      // read static data descriptor
   592                      n = dev->read(buffer, 4);
   593                      if (n < 4) {
   594                          setErrorString(tr("Invalid ZIP file. Unexpected end of file. (#1)"));
   595                          return false;
   596                      }
   597
   598                      if (buffer[0] != 'P' || !handlePossibleHeaderBegin(buffer + 1, dev, false)) {
   599                          // assume data descriptor without signature
   600                          dev->seek(dev->pos() + 8); // skip rest of the 'data_descriptor'
   601                      }
   602                  }
   603
   604  // not needed any more
   605                  /*                // here we calculate the length of the file in the zip
   606                  // with headers and jump to the next header.
   607                  uint skip = compr_size + namelen + extralen;
   608                  offset += 30 + skip;*/
   609              }
   610              pfi_map.insert(fileName, pfi);
   611          } else if (!memcmp(buffer, "PK\1\2", 4)) { // central block
   612              //qCDebug(KArchiveLog) << "PK12 found central block";
   613              startOfFile = false;
   614
   615              // so we reached the central header at the end of the zip file
   616              // here we get all interesting data out of the central header
   617              // of a file
   618              offset = dev->pos() - 4;
   619
   620              //set offset for appending new files
   621              if (d->m_offset == 0) {
   622                  d->m_offset = offset;
   623              }
   624
   625              n = dev->read(buffer + 4, 42);
   626              if (n < 42) {
   627                  setErrorString(tr(
   628                      "Invalid ZIP file, central entry too short "
   629                      "(not long enough for valid entry)"));
   630                  return false;
   631              }
   632
   633              //int gpf = (uchar)buffer[9] << 8 | (uchar)buffer[10];
   634              //qCDebug(KArchiveLog) << "general purpose flag=" << gpf;
   635              // length of the fileName (well, pathname indeed)
   636              int namelen = (uchar)buffer[29] << 8 | (uchar)buffer[28];
   637              Q_ASSERT(namelen > 0);
   638              QByteArray bufferName = dev->read(namelen);
   639              if (bufferName.size() < namelen) {
   640                  //qCWarning(KArchiveLog) << "Invalid ZIP file. Name not completely read";
   641              }
   642
   643              ParseFileInfo pfi = pfi_map.value(bufferName, ParseFileInfo());
   644
   645              QString name(QFile::decodeName(bufferName));
   646
   647              //qCDebug(KArchiveLog) << "name: " << name;
   648              // only in central header ! see below.
   649              // length of extra attributes
   650              int extralen = (uchar)buffer[31] << 8 | (uchar)buffer[30];
   651              // length of comment for this file
   652              int commlen = (uchar)buffer[33] << 8 | (uchar)buffer[32];
   653              // compression method of this file
   654              int cmethod = (uchar)buffer[11] << 8 | (uchar)buffer[10];
   655
   656              //qCDebug(KArchiveLog) << "cmethod: " << cmethod;
   657              //qCDebug(KArchiveLog) << "extralen: " << extralen;
   658
   659              // crc32 of the file
   660              uint crc32 = (uchar)buffer[19] << 24 | (uchar)buffer[18] << 16 |
   661                           (uchar)buffer[17] << 8 | (uchar)buffer[16];
   662
   663              // uncompressed file size
   664              uint ucsize = (uchar)buffer[27] << 24 | (uchar)buffer[26] << 16 |
   665                            (uchar)buffer[25] << 8 | (uchar)buffer[24];
   666              // compressed file size
   667              uint csize = (uchar)buffer[23] << 24 | (uchar)buffer[22] << 16 |
   668                           (uchar)buffer[21] << 8 | (uchar)buffer[20];
   669
   670              // offset of local header
   671              uint localheaderoffset = (uchar)buffer[45] << 24 | (uchar)buffer[44] << 16 |
   672                                       (uchar)buffer[43] << 8 | (uchar)buffer[42];
   673
   674              // some clever people use different extra field lengths
   675              // in the central header and in the local header... funny.
   676              // so we need to get the localextralen to calculate the offset
   677              // from localheaderstart to dataoffset
   678              int localextralen = pfi.extralen; // FIXME: this will not work if
   679              // no local header exists
   680
   681              //qCDebug(KArchiveLog) << "localextralen: " << localextralen;
   682
   683              // offset, where the real data for uncompression starts
   684              uint dataoffset = localheaderoffset + 30 + localextralen + namelen; //comment only in central header
   685
   686              //qCDebug(KArchiveLog) << "esize: " << esize;
   687              //qCDebug(KArchiveLog) << "eoffset: " << eoffset;
   688              //qCDebug(KArchiveLog) << "csize: " << csize;
   689
   690              int os_madeby = (uchar)buffer[5];
   691              bool isdir = false;
   692              int access = 0100644;
   693
   694              if (os_madeby == 3) {   // good ole unix
   695                  access = (uchar)buffer[40] | (uchar)buffer[41] << 8;
   696              }
   697
   698              QString entryName;
   699
   700              if (name.endsWith(QLatin1Char('/'))) { // Entries with a trailing slash are directories
   701                  isdir = true;
   702                  name = name.left(name.length() - 1);
   703                  if (os_madeby != 3) {
   704                      access = S_IFDIR | 0755;
   705                  } else {
   706                      access |= S_IFDIR | 0700;
   707                  }
   708              }
   709
   710              int pos = name.lastIndexOf(QLatin1Char('/'));
   711              if (pos == -1) {
   712                  entryName = name;
   713              } else {
   714                  entryName = name.mid(pos + 1);
   715              }
   716              Q_ASSERT(!entryName.isEmpty());
   717
   718              KArchiveEntry *entry;
   719              if (isdir) {
   720                  QString path = QDir::cleanPath(name);
   721                  const KArchiveEntry *ent = rootDir()->entry(path);
   722                  if (ent && ent->isDirectory()) {
   723                      //qCDebug(KArchiveLog) << "Directory already exists, NOT going to add it again";
   724                      entry = nullptr;
   725                  } else {
   726                      QDateTime mtime = KArchivePrivate::time_tToDateTime(pfi.mtime);
   727                      entry = new KArchiveDirectory(this, entryName, access, mtime, rootDir()->user(), rootDir()->group(), QString());
   728                      //qCDebug(KArchiveLog) << "KArchiveDirectory created, entryName= " << entryName << ", name=" << name;
   729                  }
   730              } else {
   731                  QString symlink;
   732                  if ((access & QT_STAT_MASK) == QT_STAT_LNK) {
   733                      symlink = QFile::decodeName(pfi.guessed_symlink);
   734                  }
   735                  QDateTime mtime = KArchivePrivate::time_tToDateTime(pfi.mtime);
   736                  entry = new KZipFileEntry(this, entryName, access, mtime,
   737                                            rootDir()->user(), rootDir()->group(),
   738                                            symlink, name, dataoffset,
   739                                            ucsize, cmethod, csize);
   740                  static_cast<KZipFileEntry *>(entry)->setHeaderStart(localheaderoffset);
   741                  static_cast<KZipFileEntry *>(entry)->setCRC32(crc32);
   742                  //qCDebug(KArchiveLog) << "KZipFileEntry created, entryName= " << entryName << ", name=" << name;
   743                  d->m_fileList.append(static_cast<KZipFileEntry *>(entry));
   744              }
   745
   746              if (entry) {
   747                  if (pos == -1) {
   748                      rootDir()->addEntry(entry);
   749                  } else {
   750                      // In some tar files we can find dir/./file => call cleanPath
   751                      QString path = QDir::cleanPath(name.left(pos));
   752                      // Ensure container directory exists, create otherwise
   753                      KArchiveDirectory *tdir = findOrCreate(path);
   754                      if (tdir) {
   755                          tdir->addEntry(entry);
   756                      } else {
   757                          setErrorString(tr("File %1 is in folder %2, but %3 is actually a file.").arg(entryName, path, path));
   758                          delete entry;
   759                          return false;
   760                      }
   761                  }
   762              }
   763
   764              //calculate offset to next entry
   765              offset += 46 + commlen + extralen + namelen;
   766              bool b = dev->seek(offset);
   767              Q_ASSERT(b);
   768              if (!b) {
   769                  setErrorString(tr("Could not seek to next entry"));
   770                  return false;
   771              }
   772          } else if (startOfFile) {
   773              // The file does not start with any ZIP header (e.g. self-extractable ZIP files)
   774              // Therefore we need to find the first PK\003\004 (local header)
   775              //qCDebug(KArchiveLog) << "Try to skip start of file";
   776              startOfFile = false;
   777              bool foundSignature = false;
   778
   779              while (!foundSignature) {
   780                  n = dev->read(buffer, 1);
   781                  if (n < 1) {
   782                      setErrorString(tr("Invalid ZIP file. Unexpected end of file."));
   783                      return false;
   784                  }
   785
   786                  if (buffer[0] != 'P') {
   787                      continue;
   788                  }
   789
   790                  n = dev->read(buffer, 3);
   791                  if (n < 3) {
   792                      setErrorString(tr("Invalid ZIP file. Unexpected end of file."));
   793                      return false;
   794                  }
   795
   796                  // We have to detect the magic token for a local header: PK\003\004
   797                  /*
   798                   * Note: we do not need to check the other magics, if the ZIP file has no
   799                   * local header, then it has not any files!
   800                   */
   801                  if (buffer[0] == 'K' && buffer[1] == 3 && buffer[2] == 4) {
   802                      foundSignature = true;
   803                      dev->seek(dev->pos() - 4); // go back 4 bytes, so that the magic bytes can be found...
   804                  } else {
   805                      for (int i = 0; i < 3; ++i) {
   806                          if (buffer[i] == 'P') {
   807                              // We have another P character so we must go back a little to check if it is a magic
   808                              dev->seek(dev->pos() - 3 + i);
   809                              break;
   810                          }
   811                      }
   812                  }
   813              }
   814          } else {
   815              setErrorString(
   816                  tr("Invalid ZIP file. Unrecognized header at offset %1")
   817                  .arg(dev->pos() - 4));
   818              return false;
   819          }
   820      }
   821      //qCDebug(KArchiveLog) << "*** done *** ";
   822      return true;
   823  }
   824
   825  bool KZip::closeArchive()
   826  {
   827      if (!(mode() & QIODevice::WriteOnly)) {
   828          //qCDebug(KArchiveLog) << "readonly";
   829          return true;
   830      }
   831
   832      //ReadWrite or WriteOnly
   833      //write all central dir file entries
   834
   835      // to be written at the end of the file...
   836      char buffer[22]; // first used for 12, then for 22 at the end
   837      uLong crc = crc32(0L, nullptr, 0);
   838
   839      qint64 centraldiroffset = device()->pos();
   840      //qCDebug(KArchiveLog) << "closearchive: centraldiroffset: " << centraldiroffset;
   841      qint64 atbackup = centraldiroffset;
   842      QMutableListIterator<KZipFileEntry *> it(d->m_fileList);
   843
   844      while (it.hasNext()) {
   845          //set crc and compressed size in each local file header
   846          it.next();
   847          if (!device()->seek(it.value()->headerStart() + 14)) {
   848              setErrorString(
   849                  tr("Could not seek to next file header: %1")
   850                  .arg(device()->errorString()));
   851              return false;
   852          }
   853          //qCDebug(KArchiveLog) << "closearchive setcrcandcsize: fileName:"
   854          //    << it.current()->path()
   855          //    << "encoding:" << it.current()->encoding();
   856
   857          uLong mycrc = it.value()->crc32();
   858          buffer[0] = char(mycrc); // crc checksum, at headerStart+14
   859          buffer[1] = char(mycrc >> 8);
   860          buffer[2] = char(mycrc >> 16);
   861          buffer[3] = char(mycrc >> 24);
   862
   863          int mysize1 = it.value()->compressedSize();
   864          buffer[4] = char(mysize1); // compressed file size, at headerStart+18
   865          buffer[5] = char(mysize1 >> 8);
   866          buffer[6] = char(mysize1 >> 16);
   867          buffer[7] = char(mysize1 >> 24);
   868
   869          int myusize = it.value()->size();
   870          buffer[8] = char(myusize); // uncompressed file size, at headerStart+22
   871          buffer[9] = char(myusize >> 8);
   872          buffer[10] = char(myusize >> 16);
   873          buffer[11] = char(myusize >> 24);
   874
   875          if (device()->write(buffer, 12) != 12) {
   876              setErrorString(
   877                  tr("Could not write file header: %1")
   878                  .arg(device()->errorString()));
   879              return false;
   880          }
   881      }
   882      device()->seek(atbackup);
   883
   884      it.toFront();
   885      while (it.hasNext()) {
   886          it.next();
   887          //qCDebug(KArchiveLog) << "fileName:" << it.current()->path()
   888          //              << "encoding:" << it.current()->encoding();
   889
   890          QByteArray path = QFile::encodeName(it.value()->path());
   891
   892          const int extra_field_len = (d->m_extraField == ModificationTime) ? 9 : 0;
   893          const int bufferSize = extra_field_len + path.length() + 46;
   894          char *buffer = new char[bufferSize];
   895
   896          memset(buffer, 0, 46); // zero is a nice default for most header fields
   897
   898          const char head[] = {
   899              'P', 'K', 1, 2, // central file header signature
   900              0x14, 3,        // version made by (3 == UNIX)
   901              0x14, 0         // version needed to extract
   902          };
   903
   904          // I do not know why memcpy is not working here
   905          //memcpy(buffer, head, sizeof(head));
   906          memmove(buffer, head, sizeof (head));
   907
   908          buffer[10] = char(it.value()->encoding()); // compression method
   909          buffer[11] = char(it.value()->encoding() >> 8);
   910
   911          transformToMsDos(it.value()->date(), &buffer[12]);
   912
   913          uLong mycrc = it.value()->crc32();
   914          buffer[16] = char(mycrc); // crc checksum
   915          buffer[17] = char(mycrc >> 8);
   916          buffer[18] = char(mycrc >> 16);
   917          buffer[19] = char(mycrc >> 24);
   918
   919          int mysize1 = it.value()->compressedSize();
   920          buffer[20] = char(mysize1); // compressed file size
   921          buffer[21] = char(mysize1 >> 8);
   922          buffer[22] = char(mysize1 >> 16);
   923          buffer[23] = char(mysize1 >> 24);
   924
   925          int mysize = it.value()->size();
   926          buffer[24] = char(mysize); // uncompressed file size
   927          buffer[25] = char(mysize >> 8);
   928          buffer[26] = char(mysize >> 16);
   929          buffer[27] = char(mysize >> 24);
   930
   931          buffer[28] = char(path.length()); // fileName length
   932          buffer[29] = char(path.length() >> 8);
   933
   934          buffer[30] = char(extra_field_len);
   935          buffer[31] = char(extra_field_len >> 8);
   936
   937          buffer[40] = char(it.value()->permissions());
   938          buffer[41] = char(it.value()->permissions() >> 8);
   939
   940          int myhst = it.value()->headerStart();
   941          buffer[42] = char(myhst); //relative offset of local header
   942          buffer[43] = char(myhst >> 8);
   943          buffer[44] = char(myhst >> 16);
   944          buffer[45] = char(myhst >> 24);
   945
   946          // file name
   947          strncpy(buffer + 46, path.constData(), path.length());
   948          //qCDebug(KArchiveLog) << "closearchive length to write: " << bufferSize;
   949
   950          // extra field
   951          if (d->m_extraField == ModificationTime) {
   952              char *extfield = buffer + 46 + path.length();
   953              // "Extended timestamp" header (0x5455)
   954              extfield[0] = 'U';
   955              extfield[1] = 'T';
   956              extfield[2] = 5; // data size
   957              extfield[3] = 0;
   958              extfield[4] = 1 | 2 | 4;    // specify flags from local field
   959              // (unless I misread the spec)
   960              // provide only modification time
   961              unsigned long time = (unsigned long)it.value()->date().toTime_t();
   962              extfield[5] = char(time);
   963              extfield[6] = char(time >> 8);
   964              extfield[7] = char(time >> 16);
   965              extfield[8] = char(time >> 24);
   966          }
   967
   968          crc = crc32(crc, (Bytef *)buffer, bufferSize);
   969          bool ok = (device()->write(buffer, bufferSize) == bufferSize);
   970          delete[] buffer;
   971          if (!ok) {
   972              setErrorString(
   973                  tr("Could not write file header: %1")
   974                  .arg(device()->errorString()));
   975              return false;
   976          }
   977      }
   978      qint64 centraldirendoffset = device()->pos();
   979      //qCDebug(KArchiveLog) << "closearchive: centraldirendoffset: " << centraldirendoffset;
   980      //qCDebug(KArchiveLog) << "closearchive: device()->pos(): " << device()->pos();
   981
   982      //write end of central dir record.
   983      buffer[0] = 'P'; //end of central dir signature
   984      buffer[1] = 'K';
   985      buffer[2] = 5;
   986      buffer[3] = 6;
   987
   988      buffer[4] = 0; // number of this disk
   989      buffer[5] = 0;
   990
   991      buffer[6] = 0; // number of disk with start of central dir
   992      buffer[7] = 0;
   993
   994      int count = d->m_fileList.count();
   995      //qCDebug(KArchiveLog) << "number of files (count): " << count;
   996
   997      buffer[8] = char(count); // total number of entries in central dir of
   998      buffer[9] = char(count >> 8); // this disk
   999
  1000      buffer[10] = buffer[8]; // total number of entries in the central dir
  1001      buffer[11] = buffer[9];
  1002
  1003      int cdsize = centraldirendoffset - centraldiroffset;
  1004      buffer[12] = char(cdsize); // size of the central dir
  1005      buffer[13] = char(cdsize >> 8);
  1006      buffer[14] = char(cdsize >> 16);
  1007      buffer[15] = char(cdsize >> 24);
  1008
  1009      //qCDebug(KArchiveLog) << "end : centraldiroffset: " << centraldiroffset;
  1010      //qCDebug(KArchiveLog) << "end : centraldirsize: " << cdsize;
  1011
  1012      buffer[16] = char(centraldiroffset); // central dir offset
  1013      buffer[17] = char(centraldiroffset >> 8);
  1014      buffer[18] = char(centraldiroffset >> 16);
  1015      buffer[19] = char(centraldiroffset >> 24);
  1016
  1017      buffer[20] = 0; //zipfile comment length
  1018      buffer[21] = 0;
  1019
  1020      if (device()->write(buffer, 22) != 22) {
  1021          setErrorString(
  1022              tr("Could not write central dir record: %1")
  1023              .arg(device()->errorString()));
  1024          return false;
  1025      }
  1026
  1027      return true;
  1028  }
