  1030  bool KZip::doWriteDir(const QString &name, const QString &user, const QString &group, mode_t perm,
  1031                        const QDateTime &atime, const QDateTime &mtime, const QDateTime &ctime)
  1032  {
  1033      // Zip files have no explicit directories, they are implicitly created during extraction time
  1034      // when file entries have paths in them.
  1035      // However, to support empty directories, we must create a dummy file entry which ends with '/'.
  1036      QString dirName = name;
  1037      if (!name.endsWith(QLatin1Char('/'))) {
  1038          dirName = dirName.append(QLatin1Char('/'));
  1039      }
  1040      return writeFile(dirName, QByteArray(), perm, user, group, atime, mtime, ctime);
  1041  }
  1042
  1043  bool KZip::doPrepareWriting(const QString &name, const QString &user,
  1044                              const QString &group, qint64 /*size*/, mode_t perm,
  1045                              const QDateTime &accessTime, const QDateTime &modificationTime, const QDateTime &creationTime)
  1046  {
  1047      //qCDebug(KArchiveLog);
  1048      if (!isOpen()) {
  1049          setErrorString(tr("Application error: ZIP file must be open before being written into"));
  1050          qCWarning(KArchiveLog) << "doPrepareWriting failed: !isOpen()";
  1051          return false;
  1052      }
  1053
  1054      if (!(mode() & QIODevice::WriteOnly)) { // accept WriteOnly and ReadWrite
  1055          setErrorString(tr("Application error: attempted to write into non-writable ZIP file"));
  1056          qCWarning(KArchiveLog) << "doPrepareWriting failed: !(mode() & QIODevice::WriteOnly)";
  1057          return false;
  1058      }
  1059
  1060      if (!device()) {
  1061          setErrorString(tr("Cannot create a device. Disk full?"));
  1062          return false;
  1063      }
  1064
  1065      // set right offset in zip.
  1066      if (!device()->seek(d->m_offset)) {
  1067          setErrorString(tr("Cannot seek in ZIP file. Disk full?"));
  1068          return false;
  1069      }
  1070
  1071      uint atime = accessTime.toTime_t();
  1072      uint mtime = modificationTime.toTime_t();
  1073      uint ctime = creationTime.toTime_t();
  1074
  1075      // Find or create parent dir
  1076      KArchiveDirectory *parentDir = rootDir();
  1077      QString fileName(name);
  1078      int i = name.lastIndexOf(QLatin1Char('/'));
  1079      if (i != -1) {
  1080          QString dir = name.left(i);
  1081          fileName = name.mid(i + 1);
  1082          //qCDebug(KArchiveLog) << "ensuring" << dir << "exists. fileName=" << fileName;
  1083          parentDir = findOrCreate(dir);
  1084      }
  1085
  1086      // delete entries in the filelist with the same fileName as the one we want
  1087      // to save, so that we don't have duplicate file entries when viewing the zip
  1088      // with konqi...
  1089      // CAUTION: the old file itself is still in the zip and won't be removed !!!
  1090      QMutableListIterator<KZipFileEntry *> it(d->m_fileList);
  1091      //qCDebug(KArchiveLog) << "fileName to write: " << name;
  1092      while (it.hasNext()) {
  1093          it.next();
  1094          //qCDebug(KArchiveLog) << "prepfileName: " << it.current()->path();
  1095          if (name == it.value()->path()) {
  1096              // also remove from the parentDir
  1097              parentDir->removeEntry(it.value());
  1098              //qCDebug(KArchiveLog) << "removing following entry: " << it.current()->path();
  1099              delete it.value();
  1100              it.remove();
  1101          }
  1102
  1103      }
  1104
  1105      // construct a KZipFileEntry and add it to list
  1106      KZipFileEntry *e = new KZipFileEntry(this, fileName, perm, modificationTime, user, group, QString(),
  1107                                           name, device()->pos() + 30 + name.length(), // start
  1108                                           0 /*size unknown yet*/, d->m_compression, 0 /*csize unknown yet*/);
  1109      e->setHeaderStart(device()->pos());
  1110      //qCDebug(KArchiveLog) << "wrote file start: " << e->position() << " name: " << name;
  1111      parentDir->addEntry(e);
  1112
  1113      d->m_currentFile = e;
  1114      d->m_fileList.append(e);
  1115
  1116      int extra_field_len = 0;
  1117      if (d->m_extraField == ModificationTime) {
  1118          extra_field_len = 17;    // value also used in finishWriting()
  1119      }
  1120
  1121      // write out zip header
  1122      QByteArray encodedName = QFile::encodeName(name);
  1123      int bufferSize = extra_field_len + encodedName.length() + 30;
  1124      //qCDebug(KArchiveLog) << "bufferSize=" << bufferSize;
  1125      char *buffer = new char[bufferSize];
  1126
  1127      buffer[0] = 'P'; //local file header signature
  1128      buffer[1] = 'K';
  1129      buffer[2] = 3;
  1130      buffer[3] = 4;
  1131
  1132      buffer[4] = 0x14; // version needed to extract
  1133      buffer[5] = 0;
  1134
  1135      buffer[6] = 0; // general purpose bit flag
  1136      buffer[7] = 0;
  1137
  1138      buffer[8] = char(e->encoding()); // compression method
  1139      buffer[9] = char(e->encoding() >> 8);
  1140
  1141      transformToMsDos(e->date(), &buffer[10]);
  1142
  1143      buffer[14] = 'C'; //dummy crc
  1144      buffer[15] = 'R';
  1145      buffer[16] = 'C';
  1146      buffer[17] = 'q';
  1147
  1148      buffer[18] = 'C'; //compressed file size
  1149      buffer[19] = 'S';
  1150      buffer[20] = 'I';
  1151      buffer[21] = 'Z';
  1152
  1153      buffer[22] = 'U'; //uncompressed file size
  1154      buffer[23] = 'S';
  1155      buffer[24] = 'I';
  1156      buffer[25] = 'Z';
  1157
  1158      buffer[26] = (uchar)(encodedName.length()); //fileName length
  1159      buffer[27] = (uchar)(encodedName.length() >> 8);
  1160
  1161      buffer[28] = (uchar)(extra_field_len); // extra field length
  1162      buffer[29] = (uchar)(extra_field_len >> 8);
  1163
  1164      // file name
  1165      strncpy(buffer + 30, encodedName.constData(), encodedName.length());
  1166
  1167      // extra field
  1168      if (d->m_extraField == ModificationTime) {
  1169          char *extfield = buffer + 30 + encodedName.length();
  1170          // "Extended timestamp" header (0x5455)
  1171          extfield[0] = 'U';
  1172          extfield[1] = 'T';
  1173          extfield[2] = 13; // data size
  1174          extfield[3] = 0;
  1175          extfield[4] = 1 | 2 | 4;    // contains mtime, atime, ctime
  1176
  1177          extfield[5] = char(mtime);
  1178          extfield[6] = char(mtime >> 8);
  1179          extfield[7] = char(mtime >> 16);
  1180          extfield[8] = char(mtime >> 24);
  1181
  1182          extfield[9] = char(atime);
  1183          extfield[10] = char(atime >> 8);
  1184          extfield[11] = char(atime >> 16);
  1185          extfield[12] = char(atime >> 24);
  1186
  1187          extfield[13] = char(ctime);
  1188          extfield[14] = char(ctime >> 8);
  1189          extfield[15] = char(ctime >> 16);
  1190          extfield[16] = char(ctime >> 24);
  1191      }
  1192
  1193      // Write header
  1194      bool b = (device()->write(buffer, bufferSize) == bufferSize);
  1195      d->m_crc = 0;
  1196      delete[] buffer;
  1197
  1198      if (!b) {
  1199          setErrorString(tr("Could not write to the archive. Disk full?"));
  1200          return false;
  1201      }
  1202
  1203      // Prepare device for writing the data
  1204      // Either device() if no compression, or a KFilterDev to compress
  1205      if (d->m_compression == 0) {
  1206          d->m_currentDev = device();
  1207          return true;
  1208      }
  1209
  1210      auto compressionDevice = new KCompressionDevice(device(), false, KCompressionDevice::GZip);
  1211      d->m_currentDev = compressionDevice;
  1212      compressionDevice->setSkipHeaders(); // Just zlib, not gzip
  1213
  1214      b = d->m_currentDev->open(QIODevice::WriteOnly);
  1215      Q_ASSERT(b);
  1216
  1217      if (!b) {
  1218          setErrorString(
  1219              tr("Could not open compression device: %1")
  1220              .arg(d->m_currentDev->errorString()));
  1221      }
  1222
  1223      return b;
  1224  }
  1225
  1226  bool KZip::doFinishWriting(qint64 size)
  1227  {
  1228      if (d->m_currentFile->encoding() == 8) {
  1229          // Finish
  1230          (void)d->m_currentDev->write(nullptr, 0);
  1231          delete d->m_currentDev;
  1232      }
  1233      // If 0, d->m_currentDev was device() - don't delete ;)
  1234      d->m_currentDev = nullptr;
  1235
  1236      Q_ASSERT(d->m_currentFile);
  1237      //qCDebug(KArchiveLog) << "fileName: " << d->m_currentFile->path();
  1238      //qCDebug(KArchiveLog) << "getpos (at): " << device()->pos();
  1239      d->m_currentFile->setSize(size);
  1240      int extra_field_len = 0;
  1241      if (d->m_extraField == ModificationTime) {
  1242          extra_field_len = 17;    // value also used in finishWriting()
  1243      }
  1244
  1245      const QByteArray encodedName = QFile::encodeName(d->m_currentFile->path());
  1246      int csize = device()->pos() -
  1247                  d->m_currentFile->headerStart() - 30 -
  1248                  encodedName.length() - extra_field_len;
  1249      d->m_currentFile->setCompressedSize(csize);
  1250      //qCDebug(KArchiveLog) << "usize: " << d->m_currentFile->size();
  1251      //qCDebug(KArchiveLog) << "csize: " << d->m_currentFile->compressedSize();
  1252      //qCDebug(KArchiveLog) << "headerstart: " << d->m_currentFile->headerStart();
  1253
  1254      //qCDebug(KArchiveLog) << "crc: " << d->m_crc;
  1255      d->m_currentFile->setCRC32(d->m_crc);
  1256
  1257      d->m_currentFile = nullptr;
  1258
  1259      // update saved offset for appending new files
  1260      d->m_offset = device()->pos();
  1261      return true;
  1262  }
  1263
  1264  bool KZip::doWriteSymLink(const QString &name, const QString &target,
  1265                            const QString &user, const QString &group,
  1266                            mode_t perm, const QDateTime &atime, const QDateTime &mtime, const QDateTime &ctime)
  1267  {
  1268      // reassure that symlink flag is set, otherwise strange things happen on
  1269      // extraction
  1270      perm |= QT_STAT_LNK;
  1271      Compression c = compression();
  1272      setCompression(NoCompression);  // link targets are never compressed
  1273
  1274      if (!doPrepareWriting(name, user, group, 0, perm, atime, mtime, ctime)) {
  1275          setCompression(c);
  1276          return false;
  1277      }
  1278
  1279      QByteArray symlink_target = QFile::encodeName(target);
  1280      if (!writeData(symlink_target.constData(), symlink_target.length())) {
  1281          setCompression(c);
  1282          return false;
  1283      }
  1284
  1285      if (!finishWriting(symlink_target.length())) {
  1286          setCompression(c);
  1287          return false;
  1288      }
  1289
  1290      setCompression(c);
  1291      return true;
  1292  }
