  1433  QIODevice *KZipFileEntry::createDevice() const
  1434  {
  1435      //qCDebug(KArchiveLog) << "creating iodevice limited to pos=" << position() << ", csize=" << compressedSize();
  1436      // Limit the reading to the appropriate part of the underlying device (e.g. file)
  1437      KLimitedIODevice *limitedDev = new KLimitedIODevice(archive()->device(), position(), compressedSize());
  1438      if (encoding() == 0 || compressedSize() == 0) { // no compression (or even no data)
  1439          return limitedDev;
  1440      }
  1441
  1442      if (encoding() == 8) {
  1443          // On top of that, create a device that uncompresses the zlib data
  1444          KCompressionDevice *filterDev = new KCompressionDevice(limitedDev, true, KCompressionDevice::GZip);
  1445
  1446          if (!filterDev) {
  1447              return nullptr;    // ouch
  1448          }
  1449          filterDev->setSkipHeaders(); // Just zlib, not gzip
  1450          bool b = filterDev->open(QIODevice::ReadOnly);
  1451          Q_UNUSED(b);
  1452          Q_ASSERT(b);
  1453          return filterDev;
  1454      }
  1455
  1456      qCCritical(KArchiveLog) << "This zip file contains files compressed with method"
  1457                  << encoding() << ", this method is currently not supported by KZip,"
  1458                  << "please use a command-line tool to handle this file.";
  1459      delete limitedDev;
  1460      return nullptr;
  1461  }

